import{_ as t,o as r,c as o,j as e,a as s}from"./chunks/framework.Ddwm6YJC.js";const f=JSON.parse('{"title":"第四卷 退潮 · 第96章 夏天","description":"","frontmatter":{},"headers":[],"relativePath":"第96章_夏天.md","filePath":"第96章_夏天.md"}'),n={name:"第96章_夏天.md"};function _(c,a,d,l,i,p){return r(),o("div",null,[...a[0]||(a[0]=[e("h1",{id:"第四卷-退潮-·-第96章-夏天",tabindex:"-1"},[s("第四卷 退潮 · 第96章 夏天 "),e("a",{class:"header-anchor",href:"#第四卷-退潮-·-第96章-夏天","aria-label":'Permalink to "第四卷 退潮 · 第96章 夏天"'},"​")],-1),e("p",null,"高三那个夏天来得又闷又慢。 午后蝉鸣贴着窗框往屋里钻，我把桌上的纸箱封好，胶带拉出细长的声响，指尖沾了一层薄灰。 纸箱里装着用旧的笔和草稿纸，还有几本翻卷了边的书，封口的时候，心里像是空了一块。 母亲在厨房问要不要喝绿豆汤，我说先出去走走，推开门，热气一下子裹住全身。 巷子里的阳光白得晃眼，地面晒得发软，鞋底踩上去带着轻微的黏感。 我沿着墙根走，影子被晒得很短，耳边全是蝉声，一阵高过一阵，连风都躲了起来。 走到街口，顾远家的修车铺开着门，风扇对着门口吹，门口的塑料布帘被吹得轻轻摆动。 顾远他爸坐在小马扎上补胎，手上全是黑油，抬头看见我，咧嘴一笑。 “放假了？” 我点头，走进去站在风扇前，风扑在脸上，带着机油和铁锈的味道，还有阳光晒过塑料的暖意。 风把衬衫吹得鼓起来，汗在背上一点点被吹干，凉意从皮肤外层慢慢渗进来，整个人松了半截。 陈默蹲在旁边洗链条，水盆里浮着油花，阳光一照，晃出细碎的光，水面还飘着一层淡淡的油膜，凑近闻有股铁腥混着肥皂的味。 “来得正好。”陈默甩了甩手上的水，“刚说去买冰。” 顾远从里屋探出头，手里拿着扳手，头发被汗贴在额前，脸上有一道黑印，指节也沾着油。 “老规矩，猜拳，谁输谁请。”顾远说。 顾远他爸摆手，笑声很响：“今天我请，都别抢，孩子们辛苦这么久。” 我搬了个小板凳坐在风扇边，顺手帮顾远递工具。台面上摊着一条刚卸下的内胎，破口处还沾着细沙。顾远让我按住胎边，他用锉刀来回锉破口周围，沙沙声细密，橡胶粉一点点落下来，指腹能感到胎面由光滑变粗糙。我递过去一小盒胶水，他拧开盖子，刷子在破口上薄薄刷一层，胶味有点刺，混着热气往上飘。等胶半干，他把剪好的圆胎片贴上去，用掌根用力压住，再用木柄擀了几下，边缘压得平平的，没有气泡。陈默在旁把水盆里的链条捞起来，甩掉水，挂在钩子上晾，链条滴着水珠，油花在盆里散开又聚拢。我接过打气筒，给补好的胎打气，活塞一推一拉，气筒发热，胎身慢慢鼓起，拍一拍有弹弹的闷响。整套活做完，手上也沾了薄薄一层黑，指尖搓一搓有细细的涩感。 风扇摇头，风一阵过来一阵过去，吹得人昏昏欲睡。 屋里堆着轮胎和零件，墙上挂着扳手和皮带，角落的收音机放着戏，声音被风扇搅得断断续续，偶尔清晰一句，唱腔拖得长长的。 “还是这里凉快。”我说。 “那当然，我这风扇对着街口，整条街的风都借来了。”顾远爸说。 陈默把链条挂起来晾，用毛巾擦手，毛巾很快染上一道黑印：“你这几天怎么没出来？” “收拾东西，家里乱。”我说。 “纸箱都封好了？”顾远问，一边把锉刀放回工具箱，磕出一声轻响。 “封好了，桌子都空了，看着不习惯。” 顾远他爸把补好的胎放进水盆试气，气泡咕嘟冒了一串又停住，他头也不抬：“空了好，空了才能装新的。”他把胎捞出来擦干，动作很稳，水珠顺着手腕滑进袖口。 风扇吹得桌上的旧报纸哗哗响，我伸手压住，报纸角还是翘起来，像是不服气，纸面烫烫的，晒了一上午的热。 陈默起身拍拍裤子，手上的油在裤缝蹭了两下：“走，买冰去。” 顾远他爸从围裙兜里摸出几张纸币，塞给陈默，纸币有点潮：“多拿几根，要那种最解渴的。” “我知道你要绿豆的。”陈默说。 “给沈聿拿奶油的，夏天就得吃点甜的。”顾远他爸 我笑起来：“顾远他爸记得倒清楚。” “那必须的，你们几个的口味，我闭着眼都不会拿错。”顾远他爸声音里带着笑，风把他的话吹散一点。 陈默拉着顾远往外走，两人边走边斗嘴，声音顺着巷子飘远，塑料布帘被带得晃了两下。 修车铺里只剩风扇的嗡鸣，还有顾远他爸打气的声音，一下，又一下，气筒皮碗摩擦出细细的吱声。 我闭上眼，风吹过眼皮，睫毛轻轻颤，汗味混着机油味，竟然觉得安心。手背上还有刚才按胎留下的胶的黏感，搓一搓就淡了。 没一会儿，陈默和顾远回来，怀里抱着几根冰，用塑料袋装着，外面凝着水珠，袋口滴水。 “快拿着，化了。”陈默喊。 我接过一根，冰凉顺着指尖传上来，塑料纸上沾着水，撕开时手指打滑，纸面凉得刺指。 奶油的甜香一下子漫开，咬一口，凉意顺着舌尖滑到喉咙，暑气被压下去半截，喉头都被冰得缩了一下。 顾远叼着冰，含糊不清地说：“还是顾远他爸。”他嘴角沾着奶渍，用手背一抹。 顾远他爸也拿了一根，坐在马扎上慢慢吃，吃得很珍惜，像是在品茶，咬得很小口。 “你们这个夏天，打算怎么过？”顾远他爸 陈默说：“帮家里看店，顺便学修车，跟你混。” 顾远说：“去江边游泳，再把那辆旧车修好，能骑就行。” 顾远他爸看向我：“你呢？” 我想了想，说：“还没想好，先吹吹风。”心里有段很短的回忆闪过，那年也是夏天，我和江家阿婆在老街屋檐下剥莲子，风把莲叶的清香吹过来，她笑我剥得慢，我低头不说话，只把剥好的递给她。 众人笑起来，风扇适时转过来，吹得塑料袋哗哗响。 我们都不再说话，各自吃着冰，听着蝉鸣和风扇声，时间像是被拉长了。 冰水顺着棍子流到手上，黏黏的，我换只手拿，又咬了一大口，甜在舌面上化开。 陈默吃得快，已经在嘬棍子了，顾远把冰举起来对着光看，像在看琥珀，光透过奶油部分有点朦胧。 顾远他爸去关小收音机的音量，回来坐下，叹了口气，冒出一句原声：“夏天就是好，能坐着吹风吃冰，人齐就更好。”说完他笑笑，不再多说。 “冬天也好，围着炉子喝汤。”陈默说。 “你小子就是嘴馋，什么都好。”顾远说。 我笑出声，胸口震动，郁结了许久的东西像是散开一些。 风把地上的灰吹起小小的旋，阳光从门口斜进来，照出空气里浮动的尘，尘粒在光柱里慢慢转。 陈默忽然问：“晚上去江边吗？退潮的时候可凉快了。” 顾远立刻接话：“去啊，带上西瓜，泡在水里吃。” 顾远爸摆摆手：“你们去，我看店，记得早点回。” 我低头看着手里的冰，奶油已经化了一半，奶香混着凉气往上飘。 那个名字，谁都没有提起。 像是约好了一般，话题绕着修车，绕着冰，绕着江边的风，偏偏绕开那个方向。 我心里清楚，大家都在小心翼翼地护着什么，越是闷热，越是不敢碰。 顾远看了我一眼，欲言又止，最后只说：“多吃点，吃完再拿。” 我点点头，把最后一口冰咬碎，冰碴在嘴里化开，甜得让人鼻子发酸。 陈默把棍子收集起来，整齐地码在桌上，又用纸擦了桌上的水，纸很快洇湿。 顾远他爸冰柜门，冷气扑出来，他往里看了看，忽然咦了一声。 “这底下怎么还藏着一个橘子？”顾远他爸捏出一颗黄澄澄的橘子，透着清香，皮上还凝着水珠。 陈默凑过去：“橘子？还以为早就吃完了。” 顾远也愣了一下，目光落在那个橘子上，又迅速移开，看向我。 铺子里忽然安静下来，只剩风扇的嗡鸣，一下一下，吹得人心发慌。 顾远他爸子放在桌上，推到我面前：“给你留着吧，解解渴。” 我盯着那个橘子，指尖还沾着冰水的凉，半天没有伸手。 门外蝉声骤然高起来，像潮水漫过街口，而桌上那个橘子，在阳光下泛着细小的光。 我伸出手，指尖悬在半空，门口忽然传来一道很轻的刹车声，又很快消失在蝉鸣里。 顾远他爸抬眼看向街口，笑了笑，说，瞧，风把人送来了。 我回头，塑料布帘被风掀起一角，街口空空的，只有热气在晃。",-1)])])}const h=t(n,[["render",_]]);export{f as __pageData,h as default};
